//go:build windows

package cli

import (
	"syscall"
)

// detachedSysProcAttr has no session concept to use on Windows; the child is
// already detached from the console because its stdio is redirected and the
// parent releases the process handle.
func detachedSysProcAttr() *syscall.SysProcAttr {
	return &syscall.SysProcAttr{CreationFlags: syscall.CREATE_NEW_PROCESS_GROUP}
}

// noFollowOpenFlag has no Windows equivalent in the syscall package; symlink
// creation there requires a privilege the attack this guards against does not
// have by default.
const noFollowOpenFlag = 0
//go:build !windows

package cli

import (
	"syscall"
)

// detachedSysProcAttr puts the backfill in its own session so it outlives the
// shell that started setup (the setsid/nohup pattern, without shelling out).
func detachedSysProcAttr() *syscall.SysProcAttr {
	return &syscall.SysProcAttr{Setsid: true}
}

// noFollowOpenFlag makes an open REFUSE a symlink at the final path component.
// The backfill log lives in a predictable per-repo state directory and is opened
// O_CREATE|O_APPEND as the user; without this, anything that can plant a symlink
// there redirects the child's stdout+stderr into a file of its choosing and
// appends to it as the user, for hours. It is the one write in this package that
// does not go through writeFileAtomic (a log is appended to, not replaced), so
// it needed the guard spelled out.
const noFollowOpenFlag = syscall.O_NOFOLLOW
package cli

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/entireio/entire-brain/internal/cli/internal/brainstore"
	"github.com/entireio/entire-brain/internal/cli/internal/parentwatch"
)

// spawnDetached starts the background backfill and returns immediately with the
// child's pid. Detachment is the whole point: the prompt must come back the
// instant the deterministic core is built, while an O(sessions) distill pass
// keeps running — surviving the terminal that started it.
//
// Three properties make that true:
//   - a new session/process group (see detachedSysProcAttr), so the child is not
//     killed by the shell's SIGHUP or a Ctrl-C aimed at setup;
//   - stdio pointed at a log file and /dev/null, never at the parent's terminal,
//     so a background run can never scribble over the user's prompt;
//   - Release(), so no goroutine is left waiting on the child.
func spawnDetached(plan setupBackfillPlan) (int, error) {
	if plan.Binary == "" {
		return 0, fmt.Errorf("no executable to run")
	}
	if plan.LogPath != "" {
		if err := os.MkdirAll(filepath.Dir(plan.LogPath), 0o700); err != nil {
			return 0, fmt.Errorf("create log directory: %w", err)
		}
	}
	cmd := exec.Command(plan.Binary, plan.Args...)
	cmd.Dir = plan.Dir
	env := plan.Env
	if env == nil {
		env = os.Environ()
	}
	// Exempt every detached child from the parent-death watchdog, whoever the
	// caller: outliving the spawner is the point of this function, and the
	// daemon-reregister child's parent dies by design (launchctl bootout).
	cmd.Env = append(env[:len(env):len(env)], parentwatch.DetachedEnv+"=1")
	cmd.SysProcAttr = detachedSysProcAttr()

	devNull, err := os.OpenFile(os.DevNull, os.O_RDWR, 0)
	if err != nil {
		return 0, fmt.Errorf("open %s: %w", os.DevNull, err)
	}
	defer func() { _ = devNull.Close() }()
	cmd.Stdin = devNull

	var log *os.File
	if plan.LogPath != "" {
		log, err = os.OpenFile(plan.LogPath, os.O_CREATE|os.O_WRONLY|os.O_APPEND|noFollowOpenFlag, 0o600)
		if err != nil {
			return 0, fmt.Errorf("open backfill log: %w", err)
		}
		defer func() { _ = log.Close() }()
		cmd.Stdout = log
		cmd.Stderr = log
	} else {
		cmd.Stdout = devNull
		cmd.Stderr = devNull
	}

	if err := cmd.Start(); err != nil {
		return 0, fmt.Errorf("start background backfill: %w", err)
	}
	pid := cmd.Process.Pid
	// Release the handle: setup exits in seconds and must not hold a child
	// reference for the hours the backfill may run.
	if err := cmd.Process.Release(); err != nil {
		return pid, nil
	}
	return pid, nil
}

// stopDetachedProcess prevents an untracked child from continuing to spend
//
// On linux a plain exit suffices — systemd's Restart=always relaunches the
// current binary with no signing pin — so everything but darwin is a no-op.
// Failures only cost the self-restart: the daemon still exits, launchd still
// attempts a respawn, and `setup` re-registers on its next run.
func relaunchInstalledDaemon(out io.Writer, env EntireEnv) {
	if runtime.GOOS != "darwin" || daemonRegistrationDisabled() {
		return
	}
	binary, err := os.Executable()
	if err != nil {
		fmt.Fprintf(out, "[watch] launchd re-registration skipped: %v\n", err)
		return
	}
	fmt.Fprintln(out, "[watch] re-registering with launchd so the restart lands on the current binary")
	logPath, _ := daemonLogPath(env)
	if _, err := spawnDetached(setupBackfillPlan{
		Binary:  binary,
		Args:    []string{"daemon-reregister"},
		LogPath: logPath,
	}); err != nil {
		fmt.Fprintf(out, "[watch] launchd re-registration failed (re-run `entire-brain setup` to restart the watcher): %v\n", err)
	}
}

// daemonReregisterConfig binds the re-registration engine at the assembly
// boundary: the command package never imports cli, and the unit plan, the
// registration lock, and the installer verbs stay here with `setup`.
func daemonReregisterConfig(opts Options) daemonreregister.Config {
	return daemonreregister.Config{Options: opts, Deps: daemonreregister.Deps{
		Reregister: runDaemonReregister,
	}}
}

// runDaemonReregister reinstalls the machine's one watcher under the same lock
// `setup` uses, after rechecking that the unit still exists. The recheck is
// what keeps this safe against a concurrent `setup --uninstall-daemon`:
// re-registering a unit the user just removed would resurrect a daemon they
// declined, so a missing unit file means there is nothing to restart.
func runDaemonReregister(ctx context.Context, out io.Writer, opts Options) error {
	plan, err := installedDaemonUnitPlan(opts)
	if err != nil {
		return err
	}
	if plan.NoRegister {
		return nil
			return components, err
		}
	}
	if steps.detectAgent == nil {
		steps.detectAgent = func(ctx context.Context) string {
			// No standalone announcement here: the agent is disclosed at the
			// moments it matters instead. The consent block names agent, model
			// and effort before a human answers, and the --yes path prints the
			// spend label before the detached child starts. A preamble before
			// any of that was the first line every reader saw, about a spend
			// that had not been agreed to yet (and often never happened).
			return defaultRefreshAgent(ctx, opts.Runner, repoDir)
		}
	}
	if steps.spawnBackfill == nil {
		steps.spawnBackfill = func(ctx context.Context, plan setupBackfillPlan) (int, error) {
			return spawnDetached(plan)
		}
	}
	if steps.stopBackfill == nil {
		steps.stopBackfill = stopDetachedProcess
	}
	if steps.plan == nil {
		steps.plan = func(so setupCommandOptions) (daemonPlan, error) {
			return brainWatchDaemonPlan(opts, so)
		}

package brainstore

import (
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/entireio/entire-brain/internal/cli/internal/base"
)

const FileLockRetryInterval = 10 * time.Millisecond

var ErrFileLockTimeout = errors.New("file lock timeout")

type FileLock struct {
	path        string
	file        *os.File
	processLock *processFileLock
}

// processFileLocks makes file locks visible to Go goroutines for the full
// AcquireFileLock-to-Close lifetime. The OS lock remains necessary for other
// processes.
var processFileLocks processFileLockRegistry

type processFileLockRegistry struct {
	sync.Mutex
	// os.FileInfo has no portable comparable identity, so lookup uses os.SameFile.
	locks []*processFileLock
}

type processFileLock struct {
	parent   os.FileInfo
	basename string
	token    chan struct{}
	refs     int // holders and waiters; protected by processFileLocks
}

func AcquireFileLock(path, code string, timeout time.Duration) (*FileLock, error) {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return nil, fmt.Errorf("create lock directory: %w", err)
	}
	parent, basename, err := fileLockIdentity(path)
	if err != nil {
		return nil, err
	}
	deadline := time.Now().Add(timeout)
	processLock, ok := acquireProcessFileLock(parent, basename, deadline, timeout)
	if !ok {
		return nil, fileLockTimeoutError(code, path)
	}
	defer func() {
		if processLock != nil {
			processLock.release()
		}
	}()

	for {
		if err := base.RejectUnsafeExistingRegularFile(path, "lock file"); err != nil {
			return nil, err
		}
		f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|base.FileLockOpenFlags(), 0o600)
		if err != nil {
			return nil, fmt.Errorf("open lock file: %w", err)
		}
		if err := base.RejectOpenFileAlias(path, f, "lock file"); err != nil {
			_ = f.Close()
			return nil, err
		}
		err = tryLockFile(f)
		if err == nil {
			WriteLockOwnerMetadata(path)
			lock := &FileLock{path: path, file: f, processLock: processLock}
			processLock = nil
			return lock, nil
		}
		_ = f.Close()
		if !isLockBusy(err) {
			return nil, fmt.Errorf("lock file: %w", err)
		}
		if timeout <= 0 || time.Now().Add(FileLockRetryInterval).After(deadline) {
			return nil, fileLockTimeoutError(code, path)
		}
		time.Sleep(FileLockRetryInterval)
	}
}

func fileLockIdentity(path string) (os.FileInfo, string, error) {
	parent, err := os.Stat(filepath.Dir(path))
	if err != nil {
		return nil, "", fmt.Errorf("stat lock directory: %w", err)
	}
	if !parent.IsDir() {
		return nil, "", fmt.Errorf("lock directory must be a directory: %s", filepath.Dir(path))
	}
	return parent, filepath.Base(path), nil
}

func acquireProcessFileLock(parent os.FileInfo, basename string, deadline time.Time, timeout time.Duration) (*processFileLock, bool) {
	processFileLocks.Lock()
	lock := processFileLocks.find(parent, basename)
	if lock == nil {
		lock = &processFileLock{parent: parent, basename: basename, token: make(chan struct{}, 1)}
		processFileLocks.locks = append(processFileLocks.locks, lock)
	}
	lock.refs++
	processFileLocks.Unlock()

	select {
	case lock.token <- struct{}{}:
		return lock, true
	default:
	}
	if timeout <= 0 {
		lock.releaseReference()
		return nil, false
	}
	remaining := time.Until(deadline)
	if remaining <= 0 {
		lock.releaseReference()
		return nil, false
	}
	timer := time.NewTimer(remaining)
	defer timer.Stop()
	select {
	case lock.token <- struct{}{}:
		return lock, true
	case <-timer.C:
		lock.releaseReference()
		return nil, false
	}
}

func (l *processFileLock) release() {
	<-l.token
	l.releaseReference()
}

func (r *processFileLockRegistry) find(parent os.FileInfo, basename string) *processFileLock {
	for _, lock := range r.locks {
		if lock.basename == basename && os.SameFile(lock.parent, parent) {
			return lock
		}
	}
	return nil
}

func (l *processFileLock) releaseReference() {
	processFileLocks.Lock()
	defer processFileLocks.Unlock()
	l.refs--
	if l.refs != 0 {
		return
	}
	for i, lock := range processFileLocks.locks {
		if lock == l {
			copy(processFileLocks.locks[i:], processFileLocks.locks[i+1:])
			last := len(processFileLocks.locks) - 1
			processFileLocks.locks[last] = nil
			processFileLocks.locks = processFileLocks.locks[:last]
			return
		}
	}
}

func fileLockTimeoutError(code, path string) error {
	// The holder named below is ALIVE: these are flock/LockFileEx locks, which
	// the kernel releases the moment their process exits, so a timeout can
	// never be a stale lockfile. That is what licenses naming an action here.
	return fmt.Errorf("%s: timed out acquiring lock at %s%s: %w — another entire-brain operation is still running; wait for it to finish or stop that process, then retry", code, path, describeFileLockHolder(path), ErrFileLockTimeout)
}

// fileLockMetadataMaxBytes bounds the read of an owner file.
// WriteLockOwnerMetadata writes two short lines; anything larger is not ours
// and is ignored.
const fileLockMetadataMaxBytes = 512

// FileLockOwnerSuffix names the sidecar carrying a lock's owner metadata.
//
// The metadata lives BESIDE the lock rather than inside it because Windows
// byte-range locks are MANDATORY. tryLockFile takes an exclusive LockFileEx
// over byte 0, and a read overlapping a locked range fails with
// ERROR_LOCK_VIOLATION — so metadata stored at offset 0 of the lock file is
// unreadable by any other process exactly when a holder exists, which is the
// only moment it is worth reading. POSIX flock is advisory and hides this
// completely: the same code read the metadata fine on Linux and macOS and came
// back empty-handed on Windows shard 3.
//
// Storing it at a non-zero offset inside the lock file would also work today,
// but that ties this diagnostic to the exact byte range tryLockFile happens to
// lock, so a later change there would silently break the message on Windows
// alone. A separate file nothing ever locks is the version that cannot rot.
const FileLockOwnerSuffix = ".owner"

// describeFileLockHolder turns the metadata WriteLockOwnerMetadata stores
// beside every lock into the one fact a blocked caller actually needs: WHICH
// process is holding this lock, and for how long.
//
// The pid and timestamp have been written on every acquisition since the lock
// package existed and were read by nothing, so a contended brain produced
// "brain_locked: timed out acquiring lock at .../locks/write.lock" and stopped
// there — naming the file the user already knew about and withholding the only
// thing that identifies the culprit. On a machine running a background watcher,
// a detached backfill, a watch loop and a terminal, that is the difference
// between a diagnosable stall and a mystery.
//
// It is advisory and fails silently to the empty string: the message must never
// be worse than the one it replaces. A pid whose process is gone is NOT
// reported — the OS releases the lock when its holder dies, so stale metadata
// names an innocent bystander, and naming one would be worse than naming
// nobody.
//
// The sidecar is written by the holder immediately after it wins the lock, so
// the lock itself serializes the writers and there is exactly one. It is read
// only on a TIMEOUT, which is proof somebody holds the lock right now, so the
// name it gives is the current holder — except in the instant between another
// process acquiring and stamping its own name, where it is the one just before.
// Either way it names a process that was holding this lock, which is what the
// message claims. It is never treated as proof a holder is alive: the lock
// remains the only authority on that.
func describeFileLockHolder(lockPath string) string {
	path := lockPath + FileLockOwnerSuffix
	// Lstat first, and demand a plain file. O_NOFOLLOW rejects a symlink but
	// NOT a fifo, and opening a fifo for reading blocks until someone opens the
	// write end -- which would hang the very error path whose whole job is to
	// report that we already waited long enough.
	info, err := os.Lstat(path)
	if err != nil || !info.Mode().IsRegular() {
		return ""
	}
	f, err := os.OpenFile(path, os.O_RDONLY|base.FileLockOpenFlags(), 0)
	if err != nil {
		return ""
	}
	defer func() { _ = f.Close() }()
	// Re-check through the descriptor: the path could have been swapped between
	// the Lstat and the open.
	if opened, statErr := f.Stat(); statErr != nil || !opened.Mode().IsRegular() {
		return ""
	}
	buf := make([]byte, fileLockMetadataMaxBytes)
	n, err := f.Read(buf)
	if n <= 0 || (err != nil && !errors.Is(err, io.EOF)) {
		return ""
	}
	pid := 0
	var since time.Time
	for _, line := range strings.Split(string(buf[:n]), "\n") {
		key, value, ok := strings.Cut(strings.TrimSpace(line), "=")
		if !ok {
			continue
		}
		switch key {
		case "pid":
			parsed, convErr := strconv.Atoi(value)
			if convErr == nil {
				pid = parsed
			}
		case "created_at":
			if parsed, convErr := time.Parse(time.RFC3339Nano, value); convErr == nil {
				since = parsed
			}
		}
	}
	if pid <= 0 || !ProcessAlive(pid) {
		return ""
	}
	// A holder that is US is the most valuable answer of all: it means this
	// process is blocked on a lock it already holds, which no amount of waiting
	// will resolve. Naming it as self stops the reader hunting for another
	// process.
	who := fmt.Sprintf("pid %d", pid)
	if pid == os.Getpid() {
		who = fmt.Sprintf("this process, pid %d", pid)
	}
	if since.IsZero() {
		return fmt.Sprintf(" (held by %s)", who)
	}
	held := time.Since(since)
	if held < 0 {
		held = 0
	}
	return fmt.Sprintf(" (held by %s for %s)", who, held.Round(time.Second))
}

// WriteLockOwnerMetadata records who holds lockPath, in the sidecar beside it.
// Called by the winner immediately after the lock is taken, so the lock itself
// guarantees a single writer.
//
// Best-effort throughout: a lock must never fail to be acquired because its
// diagnostic could not be written. There is deliberately no fsync — the point
// is for another PROCESS to read this within seconds, which the page cache
// already provides, and crash durability is worthless for a file whose whole
// subject is a process that no longer exists.
func WriteLockOwnerMetadata(lockPath string) {
	path := lockPath + FileLockOwnerSuffix
	if err := base.RejectUnsafeExistingRegularFile(path, "lock owner file"); err != nil {
		return
	}
	f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_TRUNC|base.FileLockOpenFlags(), 0o600)
	if err != nil {
		return
	}
	defer func() { _ = f.Close() }()
	_, _ = fmt.Fprintf(f, "pid=%d\ncreated_at=%s\n", os.Getpid(), time.Now().UTC().Format(time.RFC3339Nano))
}

func (l *FileLock) Close() error {
	if l == nil || l.file == nil {
		return nil
	}
	unlockErr := unlockFile(l.file)
	closeErr := l.file.Close()
	l.file = nil
	if l.processLock != nil {
		l.processLock.release()
		l.processLock = nil
	}
	if unlockErr != nil {
		return unlockErr
	}
	return closeErr
}
//go:build !windows

package brainstore

import (
	"errors"
	"os"

	"golang.org/x/sys/unix"
)

func tryLockFile(f *os.File) error {
	return unix.Flock(int(f.Fd()), unix.LOCK_EX|unix.LOCK_NB)
}

func unlockFile(f *os.File) error {
	return unix.Flock(int(f.Fd()), unix.LOCK_UN)
}

func isLockBusy(err error) bool {
	return errors.Is(err, unix.EWOULDBLOCK) || errors.Is(err, unix.EAGAIN)
}
